document.addEventListener('DOMContentLoaded',()=>{const ageData={'3-4':{title:'Faixa de 3 a 4 anos: Descoberta Sensorial & Coordenação',desc:'Atividades curtinhas (10 a 15 min) com pinturas com esponja, colagens grandes, carimbos divertidos e reconhecimento de cores e formas sem frustração.'},'5-6':{title:'Faixa de 5 a 6 anos: Imaginação, Recorte & Montagem',desc:'Projetos lúdicos de dobraduras fáceis, máscaras de animais, fantoches de papel e brinquedos com rolinhos que estimulam o foco e a criatividade.'},'7-8':{title:'Faixa de 7 a 8 anos: Desafios Criativos & Autonomia',desc:'Construções com recicláveis, jogos de tabuleiro caseiros, desafios de 15 minutos e criações passo a passo que a criança consegue fazer quase sozinha!'}};const ageButtons=document.querySelectorAll('.age-btn'),ageContentBox=document.getElementById('age-content-display');ageButtons.forEach(btn=>{btn.addEventListener('click',()=>{ageButtons.forEach(b=>b.classList.remove('active'));btn.classList.add('active');const key=btn.getAttribute('data-age');if(ageData[key]&&ageContentBox){ageContentBox.innerHTML=`<strong>✨ ${ageData[key].title}</strong><p style="margin-top:4px;">${ageData[key].desc}</p>`}})});const faqItems=document.querySelectorAll('.faq-item');faqItems.forEach(item=>{const btn=item.querySelector('.faq-question');btn.addEventListener('click',()=>{const isOpen=item.classList.contains('open');faqItems.forEach(other=>other.classList.remove('open'));if(!isOpen)item.classList.add('open')})});const track=document.getElementById('testimonial-track'),slides=document.querySelectorAll('.testimonial-slide'),prevBtn=document.getElementById('carousel-prev'),nextBtn=document.getElementById('carousel-next'),dots=document.querySelectorAll('.carousel-dot');if(track&&slides.length>0){let currentIndex=0,startX=0,isDragging=false;const updateCarousel=index=>{if(index<0)index=slides.length-1;if(index>=slides.length)index=0;currentIndex=index;track.style.transform=`translateX(-${currentIndex*100}%)`;dots.forEach((dot,idx)=>dot.classList.toggle('active',idx===currentIndex))};if(prevBtn)prevBtn.addEventListener('click',()=>updateCarousel(currentIndex-1));if(nextBtn)nextBtn.addEventListener('click',()=>updateCarousel(currentIndex+1));dots.forEach((dot,idx)=>dot.addEventListener('click',()=>updateCarousel(idx)));track.addEventListener('touchstart',e=>{startX=e.touches[0].clientX;isDragging=true},{passive:true});track.addEventListener('touchend',e=>{if(!isDragging)return;const diff=startX-e.changedTouches[0].clientX;if(Math.abs(diff)>40)updateCarousel(diff>0?currentIndex+1:currentIndex-1);isDragging=false},{passive:true})}const exitPopup=document.getElementById('exit-popup'),exitCloseBtn=document.getElementById('exit-popup-close');let exitPopupShown=false,historyArmed=false;const showExitPopup=()=>{if(!exitPopup||exitPopupShown)return;exitPopupShown=true;exitPopup.classList.add('active');exitPopup.setAttribute('aria-hidden','false')},hideExitPopup=()=>{if(!exitPopup)return;exitPopup.classList.remove('active');exitPopup.setAttribute('aria-hidden','true')};if(exitCloseBtn)exitCloseBtn.addEventListener('click',hideExitPopup);if(exitPopup)exitPopup.addEventListener('click',e=>{if(e.target===exitPopup)hideExitPopup()});const armBackRedirect=()=>{if(historyArmed)return;historyArmed=true;try{window.history.pushState({page:'offer-guard'},'',window.location.href)}catch(err){}};armBackRedirect();window.addEventListener('touchstart',armBackRedirect,{once:true,passive:true});window.addEventListener('click',armBackRedirect,{once:true,passive:true});window.addEventListener('popstate',()=>{if(!exitPopupShown)showExitPopup()});document.addEventListener('mouseleave',e=>{if(e.clientY<=10&&!exitPopupShown)showExitPopup()})});